def upgrade() -> None:
    """Create the ``audit_log`` table and its five read-path indexes."""
    # 1. The table: bigint-identity PK, server-set created_at, FK-free actor columns, action + target
    #    + outcome. Constraint names follow the schema's NAMING_CONVENTION (pk_audit_log).
    op.create_table(
        "audit_log",
        sa.Column("id", sa.BigInteger(), sa.Identity(always=False), nullable=False),
        sa.Column(
            "created_at",
            sa.DateTime(timezone=True),
            server_default=sa.func.now(),
            nullable=False,
        ),
        sa.Column("actor_user_id", sa.Uuid(), nullable=True),
        sa.Column("actor_key_id", sa.Uuid(), nullable=True),
        sa.Column("actor_label", sa.String(length=128), nullable=True),
        sa.Column("method", sa.String(length=10), nullable=False),
        sa.Column("path", sa.String(length=512), nullable=False),
        sa.Column("target_type", sa.String(length=64), nullable=True),
        sa.Column("target_id", sa.String(length=255), nullable=True),
        sa.Column("status_code", sa.SmallInteger(), nullable=False),
        sa.Column("correlation_id", sa.String(length=64), nullable=True),
        sa.Column("client_ip", sa.String(length=45), nullable=True),
        sa.PrimaryKeyConstraint("id", name=op.f("pk_audit_log")),
    )

    # 2. Read-path indexes for the endpoint filters + retention prune. The DESC ordering on created_at
    #    is expressed via raw text in the composite indexes (create_index column lists can't carry a
    #    per-column DESC); it matches the model's ``text("created_at DESC")`` declarations exactly.
    op.create_index(
        "ix_audit_log_created_at", "audit_log", [sa.text("created_at DESC")], unique=False
    )
    op.create_index(
        "ix_audit_log_actor_key_created",
        "audit_log",
        ["actor_key_id", sa.text("created_at DESC")],
        unique=False,
    )
    op.create_index(
        "ix_audit_log_actor_user_created",
        "audit_log",
        ["actor_user_id", sa.text("created_at DESC")],
        unique=False,
    )
    op.create_index(
        "ix_audit_log_target_created",
        "audit_log",
        ["target_type", "target_id", sa.text("created_at DESC")],
        unique=False,
    )
    op.create_index("ix_audit_log_correlation_id", "audit_log", ["correlation_id"], unique=False)


def downgrade() -> None:
    """Drop the ``audit_log`` table and its indexes (discards accumulated audit rows)."""
    # 1. Drop the indexes explicitly, then the table (drop_table would cascade them, but explicit
    #    drops keep the downgrade symmetric with the upgrade and independent of drop order).
    op.drop_index("ix_audit_log_correlation_id", table_name="audit_log")
    op.drop_index("ix_audit_log_target_created", table_name="audit_log")
    op.drop_index("ix_audit_log_actor_user_created", table_name="audit_log")
    op.drop_index("ix_audit_log_actor_key_created", table_name="audit_log")
    op.drop_index("ix_audit_log_created_at", table_name="audit_log")

    # 2. Drop the table itself.
    op.drop_table("audit_log")
